<?php
ini_set('display_errors', 1);
error_reporting(E_ALL);

header('Content-Type: application/json; charset=utf-8');
header("Access-Control-Allow-Origin: *");

// 0. Auto-Update Installer from GitHub if requested
if (isset($_GET['auto_update']) || isset($_GET['update_from_github'])) {
    $remoteUrl = 'https://raw.githubusercontent.com/ankit261194/shri-balaji-kripa-dham/main/backend/install.php';
    $remoteCode = false;
    if (function_exists('curl_init')) {
        $ch = curl_init($remoteUrl);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true);
        curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);
        curl_setopt($ch, CURLOPT_TIMEOUT, 20);
        $remoteCode = curl_exec($ch);
        curl_close($ch);
    }
    if (!$remoteCode) {
        $remoteCode = @file_get_contents($remoteUrl);
    }
    if ($remoteCode && strpos($remoteCode, '<?php') !== false && strlen($remoteCode) > 5000) {
        file_put_contents(__FILE__, $remoteCode);
        require __FILE__;
        exit;
    }
}

$baseDir = __DIR__;
$createdFiles = [];

// 1. Create Directories
$dirs = ['api', 'config', 'uploads', 'uploads/sevadars', 'uploads/donors', 'downloads', 'vault', 'vault/snapshots'];
foreach ($dirs as $d) {
    $p = $baseDir . '/' . $d;
    if (!is_dir($p)) {
        @mkdir($p, 0755, true);
    }
}

// 2. Deploy Files
$files = [
    '.htaccess' => base64_decode(''),
    'download.php' => base64_decode(''),
    'index.php' => base64_decode(''),
    'schema.sql' => base64_decode(''),
    'config/db.php' => base64_decode(''),
    'api/book_bus_seat.php' => base64_decode(''),
    'api/cloud_sync.php' => base64_decode(''),
    'api/daily_darshan.php' => base64_decode(''),
    'api/data_vault.php' => base64_decode(''),
    'api/delete_donor.php' => base64_decode(''),
    'api/delete_expense.php' => base64_decode(''),
    'api/delete_sevadar.php' => base64_decode(''),
    'api/drive_autosync.php' => base64_decode(''),
    'api/get_bus_seats.php' => base64_decode(''),
    'api/get_donors.php' => base64_decode(''),
    'api/get_expenses.php' => base64_decode(''),
    'api/get_face_profiles.php' => base64_decode(''),
    'api/get_parchas.php' => base64_decode(''),
    'api/get_payments.php' => base64_decode(''),
    'api/get_queue.php' => base64_decode(''),
    'api/get_sevadars.php' => base64_decode(''),
    'api/github_proxy.php' => base64_decode(''),
    'api/issue_token.php' => base64_decode(''),
    'api/live_config.php' => base64_decode(''),
    'api/panchang_today.php' => base64_decode(''),
    'api/register_fcm_token.php' => base64_decode(''),
    'api/save_donor.php' => base64_decode(''),
    'api/save_expense.php' => base64_decode(''),
    'api/save_parcha.php' => base64_decode(''),
    'api/save_payment.php' => base64_decode(''),
    'api/save_sevadar.php' => base64_decode(''),
    'api/send_fcm.php' => base64_decode(''),
    'api/stream_audio.php' => base64_decode(''),
    'api/sync_face_profile.php' => base64_decode(''),
    'api/update_token_status.php' => base64_decode(''),
    'api/upload_photo.php' => base64_decode('')
];

foreach ($files as $name => $content) {
    $dest = $baseDir . '/' . $name;
    $parent = dirname($dest);
    if (!is_dir($parent)) {
        @mkdir($parent, 0755, true);
    }
    if (file_put_contents($dest, $content) !== false) {
        $createdFiles[] = $name;
    }
}

// 3. Database Connection & Schema Migration
if (file_exists($baseDir . '/config/db.php')) {
    require_once $baseDir . '/config/db.php';
}

$pdo = function_exists('getDB') ? getDB() : null;
$results = [];

if ($pdo) {
    // Ensure all tables exist from schema
    if (file_exists($baseDir . '/schema.sql')) {
        $schema = file_get_contents($baseDir . '/schema.sql');
        $queries = array_filter(array_map('trim', explode(';', $schema)));
        foreach ($queries as $q) {
            if (!empty($q)) {
                try {
                    $pdo->exec($q);
                    $results[] = ["query" => substr($q, 0, 50) . "...", "status" => "OK"];
                } catch (Exception $e) {
                    $results[] = ["query" => substr($q, 0, 50) . "...", "status" => "ERROR: " . $e->getMessage()];
                }
            }
        }
    }

    // Ensure google_drive_webhook_url exists in ashram_settings
    try {
        $pdo->exec("ALTER TABLE ashram_settings ADD COLUMN IF NOT EXISTS google_drive_webhook_url VARCHAR(500) DEFAULT ''");
    } catch (Exception $e) {}

    // Ensure daily_darshan table exists
    try {
        $pdo->exec("CREATE TABLE IF NOT EXISTS daily_darshan (
            id BIGINT AUTO_INCREMENT PRIMARY KEY,
            darshan_date DATE NOT NULL,
            title VARCHAR(255) NOT NULL DEFAULT 'आज का पावन बाल स्वरूप दर्शन',
            shringar_description TEXT,
            photo_url VARCHAR(500) NOT NULL,
            aarti_time VARCHAR(100) DEFAULT 'प्रातः 8:00 बजे',
            auspicious_chaupai TEXT,
            views_count INT NOT NULL DEFAULT 108,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE KEY uk_darshan_date (darshan_date)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    } catch (Exception $e) {}

    // Ensure default ashram_settings row
    try {
        $pdo->exec("INSERT IGNORE INTO ashram_settings (id, ashram_name, current_serving_token, is_darbar_active, is_token_service_enabled) VALUES (1, 'श्री बालाजी कृपा धाम', 0, 1, 1)");
    } catch (Exception $e) {}
}

$tablesStmt = $pdo ? $pdo->query("SHOW TABLES") : null;
$existingTables = $tablesStmt ? $tablesStmt->fetchAll(PDO::FETCH_COLUMN) : [];

echo json_encode([
    "success" => true,
    "status" => "WEBSITE_AND_CENTRAL_API_ONLINE",
    "version" => "v2.50.0",
    "message" => "श्री बालाजी कृपा धाम आधिकारिक वेबसाइट, अखंड डेटा वॉल्ट व 30+ APIs 100% तैनात व अपडेटेड!",
    "installed_files_count" => count($createdFiles),
    "installed_files" => $createdFiles,
    "tables_in_database" => $existingTables
], JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT);
